.guide {
  z-index: 9999;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  pointer-events: none;
  opacity: 1;
  min-height: 100vh;
  background-attachment: local;
}

.guide--layer {
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  min-height: 100vh;
  pointer-events: none;
  z-index: 9999;
}
.guide--layer.active {
  display: block !important;
}

.guide--graph {
  z-index: 9999;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  pointer-events: none;
  opacity: 1;
  min-height: 100vh;
  background-attachment: local;
  background-repeat: repeat;
  background-size: 1.25rem 1.25rem;
  background-image: repeating-linear-gradient(to right, rgba(111, 124, 126, 0.483) 0, rgba(111, 124, 126, 0.483) 1px, transparent 1px, transparent 1.25rem), repeating-linear-gradient(to bottom, rgba(111, 124, 126, 0.483) 0, rgba(111, 124, 126, 0.483) 1px, transparent 1px, transparent 1.25rem);
}

.guide--graph_centered {
  z-index: 9999;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  pointer-events: none;
  opacity: 1;
  min-height: 100vh;
  background-attachment: local;
  background-repeat: repeat;
  background-size: 1.25rem 1.25rem;
  background-position: calc(50% - 15rem / 2) 0;
  background-image: repeating-linear-gradient(to right, rgba(111, 124, 126, 0.483) 0, rgba(111, 124, 126, 0.483) 1px, transparent 1px, transparent 1.25rem), repeating-linear-gradient(to bottom, rgba(111, 124, 126, 0.483) 0, rgba(111, 124, 126, 0.483) 1px, transparent 1px, transparent 1.25rem);
}

.guide--baseline {
  z-index: 9999;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  pointer-events: none;
  opacity: 1;
  min-height: 100vh;
  background-attachment: local;
  background-repeat: repeat;
  background-size: 100% 1.25rem;
  background-image: repeating-linear-gradient(to bottom, rgb(0, 200, 255) 0 1px, transparent 1px 100%);
}

html {
  font-size: 12px;
}
@media screen and (min-width: 320px) {
  html {
    font-size: calc(12px + 12 * (100vw - 320px) / 1120);
  }
}
@media screen and (min-width: 1440px) {
  html {
    font-size: 24px;
  }
}

